"""pt — prophets_c."""

T = {
"prophets_151": ("Do que foi proibido a Adão e à sua esposa aproximarem-se no Jardim?", ["De uma árvore", "De um rio", "De uma porta", "De uma montanha"], "Allah permitiu-lhes comer à vontade, exceto aproximarem-se de uma única árvore."),
"prophets_152": ("Segundo o Alcorão, o que recebeu Adão do seu Senhor após a sua falta?", ["Palavras (de arrependimento), e Allah aceitou o seu arrependimento", "Riqueza", "Um reino", "Um livro"], "«Adão recebeu palavras do seu Senhor, e Ele aceitou o seu arrependimento»."),
"prophets_153": ("Com quem compara o Alcorão 'Isa quanto à sua criação?", ["Com Adão, criado do pó", "Com Nuh (Noé)", "Com Ibrahim (Abraão)", "Com Yahya (João)"], "«O caso de 'Isa perante Allah é como o de Adão: criou-o do pó e depois disse-lhe: “Sê”, e foi»."),
"prophets_154": ("De que profeta diz o Alcorão que era veraz e que Allah o elevou a uma posição elevada?", ["Idris (Enoque)", "Ilyas (Elias)", "Dhul-Kifl", "Al-Yasa' (Eliseu)"], "«E menciona Idris no Livro: era veraz, um profeta; e elevámo-lo a uma posição elevada»."),
"prophets_155": ("O que disse Nuh quando os seus embarcaram na arca?", ["«Em nome de Allah seja o seu curso e o seu ancoradouro»", "«Não temais o mar»", "«Levai as vossas provisões»", "«Esperai a noite»"], "«Embarcai nela: em nome de Allah seja o seu curso e o seu ancoradouro»."),
"prophets_156": ("Na sura Nuh, o que pediu o profeta Nuh ao seu Senhor a respeito dos incrédulos?", ["Que não deixasse nenhum deles sobre a terra", "Que os enriquecesse", "Que lhes desse mais um ano", "Que os exilasse"], "«Senhor meu, não deixes sobre a terra nenhum incrédulo»."),
"prophets_157": ("Quantos de cada espécie devia Nuh levar a bordo da arca?", ["Um par", "Três", "Dez", "Apenas um"], "Allah ordenou-lhe que carregasse nela um par de cada espécie, juntamente com a sua família."),
"prophets_158": ("Hud lembrou a 'Ad que Allah os fizera sucessores depois de que povo?", ["Do povo de Nuh (Noé)", "Do povo de Lut (Ló)", "Do povo de Musa (Moisés)", "Do povo de Sabá"], "«Lembrai-vos de quando Ele vos fez sucessores depois do povo de Nuh e vos aumentou em estatura»."),
"prophets_159": ("Com que foi destruído o povo de 'Ad, segundo a sura Al-Haqqa?", ["Com um vento gélido e bramante", "Com um dilúvio", "Com um terramoto", "Com uma praga de gafanhotos"], "«Quanto a 'Ad, foram destruídos por um vento glacial e violento»."),
"prophets_160": ("O que censurou Hud ao seu povo, que edificava em cada altura?", ["Edificar por vaidade e esperar viver eternamente", "Cultivar a terra", "Comerciar longe", "Viajar de noite"], "«Edificais em cada altura um monumento por diversão, e tomais palácios como se fôsseis viver eternamente?»"),
"prophets_161": ("O que fazia Thamud com as montanhas, segundo o Alcorão?", ["Talhava nelas as suas casas", "Escondia ouro nelas", "Apascentava rebanhos nelas", "Evitava-as"], "«Tomais palácios nas suas planícies e talhais casas nas montanhas»."),
"prophets_162": ("Segundo a sura Al-Qamar, como que foi enviada a camela a Thamud?", ["Como prova para eles", "Como recompensa", "Como presente do seu rei", "Como rebanho para vender"], "«Vamos enviar-lhes a camela como prova: observa-os e sê paciente»."),
"prophets_163": ("O que se apoderou de Thamud depois de matarem a camela?", ["O terramoto (ar-rajfa)", "O dilúvio", "O vento gélido", "A fome"], "«O terramoto apoderou-se deles, e amanheceram jazendo nas suas casas»."),
"prophets_164": ("Que profeta foi enviado ao povo que cometia a grande indecência, dizendo-lhes «Não temeis Allah?»", ["Lut (Ló)", "Salih", "Hud", "Shu'ayb"], "«Quando o seu irmão Lut lhes disse: “Não temeis Allah?”»"),
"prophets_165": ("O que foi ordenado a Lut na noite do castigo?", ["Partir de noite com a sua família e não olhar para trás", "Reunir o seu povo", "Esperar a alvorada", "Esconder-se na montanha"], "«Parte, pois, com a tua família numa parte da noite, e que nenhum de vós olhe para trás»."),
"prophets_166": ("Que profeta foi enviado ao povo de Madian, que fraudava na medida e no peso?", ["Shu'ayb", "Lut (Ló)", "Hud", "Ilyas (Elias)"], "Shu'ayb ordenou-lhes dar a medida completa e o peso justo, e não semear corrupção na terra."),
"prophets_167": ("O que disse Shu'ayb ao seu povo sobre o que realmente queria?", ["«Só quero a reforma, na medida das minhas forças»", "«Só quero riqueza»", "«Quero governar»", "«Quero partir»"], "«Só quero a reforma, na medida das minhas forças. E o meu êxito só depende de Allah»."),
"prophets_168": ("Depois de Allah provar Ibrahim com mandamentos que ele cumpriu, o que lhe disse?", ["«Vou fazer de ti um guia (imam) para os homens»", "«Vou dar-te um reino»", "«Vou enriquecer-te»", "«Vou fazer-te rei da Babilónia»"], "«Vou fazer de ti um guia para os homens». Ibrahim perguntou: «E da minha descendência?»"),
"prophets_169": ("Como deixou Ibrahim sem resposta o rei que pretendia dar a vida e a morte?", ["«Allah traz o sol do oriente: traze-o tu do ocidente»", "«Faz cair a chuva»", "«Move essa montanha»", "«Conta as estrelas»"], "«Allah traz o sol do oriente; traze-o tu do ocidente». E o incrédulo ficou confundido."),
"prophets_170": ("O que foi ordenado a Ibrahim proclamar aos homens sobre a Casa Sagrada?", ["A peregrinação: virão a pé e em toda montaria", "O comércio", "A guerra", "O silêncio"], "«E proclama aos homens a peregrinação: virão a ti a pé e em toda montaria esbelta»."),
"prophets_171": ("O que ofereceu Ibrahim aos seus hóspedes honrados, que não lhe tocaram?", ["Um vitelo gordo assado", "Pão e água", "Tâmaras", "Leite"], "Foi ter com os seus e trouxe um vitelo gordo; ao ver que não estendiam as mãos para ele, sentiu temor."),
"prophets_172": ("De quem diz o Alcorão que é «um belo exemplo» (uswa hasana) para os crentes, com aqueles que estavam com ele?", ["Ibrahim (Abraão)", "Nuh (Noé)", "Musa (Moisés)", "Dawud (David)"], "«Tendes um belo exemplo em Ibrahim e naqueles que estavam com ele»."),
"prophets_173": ("Na sura Ibrahim, o que pediu Ibrahim para a cidade de Meca?", ["Que fosse segura, e que ele e os seus filhos se livrassem de adorar ídolos", "Que se tornasse um grande mercado", "Que tivesse palácios", "Que ficasse deserta"], "«Senhor meu, faz desta cidade um lugar seguro, e livra-me a mim e aos meus filhos de adorar ídolos»."),
"prophets_174": ("O que disse Ibrahim ao deixar o seu povo?", ["«Vou para o meu Senhor: Ele guiar-me-á»", "«Vou buscar fortuna»", "«Voltarei para os combater»", "«Vou para o Egito»"], "«Vou para o meu Senhor: Ele guiar-me-á»."),
"prophets_175": ("De que profeta diz o Alcorão que era «fiel à sua promessa» e ordenava aos seus a oração e o zakat?", ["Isma'il (Ismael)", "Ishaq (Isaac)", "Ya'qub (Jacob)", "Yusuf (José)"], "«Era fiel à sua promessa; foi um mensageiro e um profeta. Ordenava à sua família a oração e o zakat»."),
"prophets_176": ("O que aconselhou Ya'qub a Yusuf depois do seu sonho?", ["Que não o contasse aos seus irmãos", "Que o contasse a todos", "Que o escrevesse", "Que o esquecesse"], "«Ó meu filho, não contes a tua visão aos teus irmãos, para que não tramem contra ti»."),
"prophets_177": ("Que indício estabeleceu a inocência de Yusuf perante o senhor da casa?", ["A sua túnica rasgada por trás", "Uma testemunha escondida", "Uma carta", "Um juramento"], "Se a túnica estava rasgada por trás, ela mentiu e ele está entre os veracíssimos."),
"prophets_178": ("O que fizeram as mulheres da cidade ao ver Yusuf?", ["Cortaram as mãos, tomadas de admiração", "Fugiram", "Calaram-se", "Riram"], "«Quando o viram, ficaram maravilhadas e cortaram as mãos, dizendo: “Este não é um ser humano; não é senão um anjo nobre!”»"),
"prophets_179": ("O que ensinou Yusuf aos seus dois companheiros de prisão antes de interpretar os seus sonhos?", ["A unicidade de Allah, e que o juízo só a Ele pertence", "A medicina", "O cálculo das colheitas", "A poesia"], "«São melhores senhores separados, ou Allah, o Único, o Dominador? … O juízo só pertence a Allah»."),
"prophets_180": ("O que disse o rei do Egito a Yusuf depois de falar com ele?", ["«Hoje tens junto de nós posição firme e confiança»", "«Volta para a prisão»", "«Sai do Egito»", "«Dou-te a minha filha»"], "«Quando falou com ele, disse: “Hoje tens junto de nós posição firme e confiança”»."),
"prophets_181": ("Como reteve Yusuf o seu irmão consigo?", ["A taça do rei foi encontrada na bagagem do seu irmão", "Comprou-o", "Prendeu-o sem motivo", "Nomeou-o ministro"], "«Assim inspirámos essa estratagema a Yusuf»: a taça saiu do saco do seu irmão."),
"prophets_182": ("O que disse Yusuf aos seus irmãos quando reconheceram a sua falta?", ["«Hoje não há censura contra vós»", "«Sereis castigados»", "«Ide-vos e não volteis»", "«Esqueci-vos»"], "«Hoje não há censura contra vós. Que Allah vos perdoe: Ele é o mais misericordioso dos misericordiosos»."),
"prophets_183": ("O que disse Ya'qub aos seus filhos sobre o desespero?", ["«Não desespereis da misericórdia de Allah»", "«Não volteis a partir»", "«Não faleis com ninguém»", "«Não escrevais nada»"], "«Não desespereis do alívio de Allah: só desesperam dele os incrédulos»."),
"prophets_184": ("Que súplica fez Yusuf no fim da sua história?", ["Morrer submisso (muçulmano) e ser reunido com os justos", "Reinar sobre todo o Egito", "Voltar a Canaã", "Viver muito tempo"], "«Faz-me morrer submisso e reúne-me com os justos»."),
"prophets_185": ("Como se dirigiu Ayyub ao seu Senhor na provação?", ["«Tocou-me a desgraça, e Tu és o mais Misericordioso»", "«Porquê eu?»", "«Devolve-me a minha riqueza»", "«Destrói os meus inimigos»"], "«E lembra-te do Nosso servo Ayyub, quando invocou o seu Senhor: “O demónio infligiu-me fadiga e castigo”»."),
"prophets_186": ("O que devolveu Allah a Ayyub após a provação, segundo a sura Sad?", ["A sua família, e outro tanto com eles", "Um reino", "Um navio", "Um rebanho de camelos"], "«Devolvemos-lhe a sua família e outro tanto com eles, como misericórdia da Nossa parte e lembrança para os dotados de entendimento»."),
"prophets_187": ("Segundo a sura As-Saffat, o que salvou Yunus de permanecer no ventre do peixe?", ["Que era dos que glorificam Allah", "A sua força", "Um navio que passava", "Um vento favorável"], "«Se não tivesse sido dos que glorificam, teria permanecido no seu ventre até ao dia em que forem ressuscitados»."),
"prophets_188": ("Que povo, segundo o Alcorão, creu antes de o castigo o atingir, e isso lhe aproveitou?", ["O povo de Yunus (Jonas)", "O povo de Nuh", "O povo de Lut", "O povo de Hud"], "«Acaso houve uma cidade que cresse e a quem aproveitasse a sua fé, exceto o povo de Yunus?»"),
"prophets_189": ("Como designa o Alcorão Yunus quando ordena ao Profeta ﷺ não ser como ele na sua impaciência?", ["«O companheiro do peixe» (sahib al-hut)", "«O homem do bastão»", "«O homem da montanha»", "«O homem do poço»"], "«E não sejas como o companheiro do peixe, quando invocou cheio de angústia»."),
"prophets_190": ("Que profeta censurou o seu povo por invocar Ba'l e abandonar o melhor dos criadores?", ["Ilyas (Elias)", "Al-Yasa' (Eliseu)", "Yunus (Jonas)", "Shu'ayb"], "«Ilyas foi dos mensageiros… “Invocais Ba'l e abandonais o melhor dos criadores?”»"),
"prophets_191": ("Junto de Isma'il e Idris, que profeta menciona o Alcorão entre os pacientes que Allah admitiu na Sua misericórdia?", ["Dhul-Kifl", "Ilyas (Elias)", "Yunus (Jonas)", "Al-Yasa' (Eliseu)"], "«E Isma'il, Idris e Dhul-Kifl: todos foram dos pacientes. E admitimo-los na Nossa misericórdia»."),
"prophets_192": ("O que fez Allah pelos Filhos de Israel diante do mar, perseguidos pelo Faraó?", ["Abriu o mar e salvou-os", "Fez cair a noite", "Enviou navios", "Secou o mar para sempre"], "«E quando abrimos o mar para vós: salvámo-vos e afogámos o povo do Faraó»."),
"prophets_193": ("Porque pediu Musa a Allah que enviasse Harun com ele?", ["Porque era mais eloquente do que ele", "Porque era mais velho", "Porque conhecia o Egito", "Porque sabia escrever"], "«O meu irmão Harun é mais eloquente do que eu: envia-o, pois, comigo como apoio que me confirme»."),
"prophets_194": ("Como deviam Musa e Harun falar ao Faraó?", ["Com palavras suaves", "Com ameaças", "Sem olhar para ele", "Só por escrito"], "«E falai-lhe com palavras suaves: talvez se recorde ou tema»."),
"prophets_195": ("Quem, da família do Faraó, defendeu Musa ocultando a sua fé?", ["Um homem crente da família do Faraó", "O sumo sacerdote", "O chefe do exército", "O vizir Haman"], "«E um homem crente da família do Faraó, que ocultava a sua fé, disse: “Ides matar um homem porque diz: o meu Senhor é Allah?”»"),
"prophets_196": ("O que disse Harun ao seu povo durante a ausência de Musa?", ["Que estavam apenas a ser provados com o bezerro, e deviam segui-lo", "Que guardassem o bezerro", "Que partissem para o Egito", "Que se calassem"], "«Ó meu povo, estais apenas a ser provados com ele. O vosso Senhor é o Clemente: segui-me»."),
"prophets_197": ("O que disse a mulher do Faraó ao encontrar o menino Musa?", ["«Será alegria para os meus olhos e para os teus: não o mateis»", "«Devolvei-o à sua mãe»", "«Levai-o ao rio»", "«Vendei-o»"], "«E disse a mulher do Faraó: “Alegria para os meus olhos e para os teus. Não o mateis: talvez nos seja útil”»."),
"prophets_198": ("Como pediu Musa para seguir o servo sábio (al-Khidr)?", ["«Posso seguir-te, com a condição de que me ensines?»", "«Ordena-me e obedecerei»", "«Ensina-me a troco de pagamento»", "«Vem comigo»"], "«Posso seguir-te com a condição de que me ensines algo da boa direção que te foi ensinada?»"),
"prophets_199": ("Em que estado voltou Musa ao seu povo depois de ver o bezerro?", ["Irado e aflito", "Alegre", "Silencioso", "Indiferente"], "«E quando Musa voltou ao seu povo, irado e aflito… atirou as Tábuas»."),
"prophets_200": ("Que mensagem devia Musa levar ao Faraó, segundo a sura An-Nazi'at?", ["«Queres purificar-te, e que eu te guie ao teu Senhor?»", "«Devolve-me o meu povo»", "«Constrói-me um palácio»", "«Sai do Egito»"], "«Vai ao Faraó: ele excedeu-se. E dize-lhe: queres purificar-te, e que eu te guie ao teu Senhor para que O temas?»"),
"prophets_201": ("Quem glorificava Allah juntamente com Dawud, ao entardecer e ao amanhecer?", ["As montanhas e as aves", "Os rios", "As estrelas", "Os ventos"], "«Submetemos as montanhas para que glorificassem com ele ao entardecer e ao amanhecer, e as aves reunidas»."),
"prophets_202": ("O que diz o Alcorão que Allah deu a Dawud, junto com um reino firme?", ["A sabedoria e o discurso decisivo", "Exércitos imensos", "Ouro e prata", "Um palácio de marfim"], "«Fortalecemos o seu reino e demos-lhe a sabedoria e o discernimento no falar»."),
"prophets_203": ("O que foi ordenado a Dawud ao fabricar as cotas de malha?", ["Medir bem os elos", "Gravar nelas o seu nome", "Dourá-las", "Vendê-las"], "«Faz cotas de malha completas, e mede bem os elos»."),
"prophets_204": ("O que disseram Dawud e Sulaiman quando Allah lhes deu o conhecimento?", ["«Louvado seja Allah, que nos favoreceu sobre muitos dos Seus servos crentes»", "«Somos os melhores»", "«Ninguém nos iguala»", "«Merecemo-lo»"], "«Louvado seja Allah, que nos favoreceu sobre muitos dos Seus servos crentes»."),
"prophets_205": ("O que fez Sulaiman ao ouvir a formiga avisar os seus?", ["Sorriu e pediu a Allah ser grato", "Zangou-se", "Desviou o seu exército em silêncio", "Ordenou silêncio"], "«Sorriu ao ouvir as suas palavras e disse: “Senhor meu, permite-me agradecer o Teu favor”»."),
"prophets_206": ("Que notícia trouxe a poupa a Sulaiman?", ["Que uma mulher reinava em Sabá e o seu povo se prostrava ao sol", "Que um exército se aproximava", "Que havia seca", "Que havia um tesouro escondido"], "«Venho de Sabá com uma notícia certa: encontrei uma mulher que reina sobre eles… prostram-se ao sol»."),
"prophets_207": ("O que espantou a rainha de Sabá ao entrar no palácio de Sulaiman?", ["O chão de cristal, que tomou por água", "Um leão amansado", "Um jardim suspenso", "Um trono de ouro"], "«Foi-lhe dito: “Entra no palácio”. Ao vê-lo, tomou-o por água profunda e descobriu as pernas. Ele disse: “É um palácio pavimentado de cristal”»."),
"prophets_208": ("De que eram compostos os exércitos de Sulaiman, segundo o Alcorão?", ["De génios, homens e aves", "Só de cavaleiros", "De marinheiros", "Só de arqueiros"], "«E foram reunidos para Sulaiman os seus exércitos de génios, homens e aves, em filas ordenadas»."),
"prophets_209": ("Como descreveu Zakariyya o seu estado ao invocar o seu Senhor?", ["«Os meus ossos enfraqueceram e a minha cabeça acendeu-se de cãs»", "«Sou rico e saciado»", "«Estou longe do meu povo»", "«Estou em viagem»"], "«Senhor meu, os meus ossos enfraqueceram e a minha cabeça acendeu-se de cãs, e nunca fui infeliz ao invocar-Te»."),
"prophets_210": ("Que sinal foi dado a Zakariyya pelo nascimento de Yahya?", ["Não falar às pessoas durante três dias, senão por gestos", "Uma estrela", "Chuva fora de estação", "Um sonho repetido"], "«O teu sinal é que não falarás às pessoas durante três dias, senão por gestos»."),
"prophets_211": ("O que foi dito a Yahya a respeito do Livro?", ["«Toma o Livro com força»", "«Esconde o Livro»", "«Copia o Livro»", "«Lê-o uma vez»"], "«Ó Yahya, toma o Livro com determinação!» E demos-lhe a sabedoria ainda criança."),
"prophets_212": ("O que ordenaram os anjos a Maryam depois de lhe anunciarem a sua eleição?", ["Ser devota ao seu Senhor, prostrar-se e inclinar-se", "Empreender uma viagem", "Calar-se para sempre", "Ensinar no Templo"], "«Ó Maryam, sê devota ao teu Senhor, prostra-te e inclina-te com os que se inclinam»."),
"prophets_213": ("O que foi dito a Maryam para sacudir e comer, no momento do parto?", ["O tronco da palmeira, para caírem tâmaras frescas", "Uma oliveira", "Uma figueira", "Uma videira"], "«Sacode para ti o tronco da palmeira: fará cair sobre ti tâmaras frescas e maduras»."),
"prophets_214": ("O que disse 'Isa no berço sobre o que Allah lhe recomendara?", ["A oração e o zakat enquanto vivesse", "O comércio", "O silêncio", "A viagem"], "«Recomendou-me a oração e o zakat enquanto eu viver»."),
"prophets_215": ("Como descreve a sura Az-Zukhruf 'Isa filho de Maryam?", ["Um servo a quem Allah agraciou e fez exemplo para os Filhos de Israel", "Um rei de Israel", "Um anjo descido", "Um escriba do Templo"], "«Não foi senão um servo a quem agraciámos e fizemos exemplo para os Filhos de Israel»."),
"prophets_216": ("O que responderá 'Isa no Dia da Ressurreição quando Allah o interrogar?", ["«Glória a Ti! Não me cabe dizer o que não tenho direito de dizer»", "«Não me lembro»", "«Foram eles que escreveram»", "«Pergunta aos discípulos»"], "«Glória a Ti! Não me cabe dizer o que não tenho direito de dizer»."),
"prophets_217": ("Como descreve o Alcorão 'Isa filho de Maryam?", ["O mensageiro de Allah, a Sua palavra dirigida a Maryam e um espírito d'Ele procedente", "Um anjo enviado", "Um rei justo", "Um escriba sábio"], "«O Messias, 'Isa filho de Maryam, não é senão o mensageiro de Allah, a Sua palavra que dirigiu a Maryam e um espírito d'Ele procedente»."),
"prophets_218": ("Na sura Ad-Duha, de que favores recorda Allah ao Seu Profeta ﷺ?", ["Acolheu-o órfão, guiou-o e enriqueceu-o", "Deu-lhe um reino", "Deu-lhe um exército", "Deu-lhe um palácio"], "«Não te encontrou órfão e te acolheu? E não te encontrou perdido e te guiou? E não te encontrou pobre e te enriqueceu?»"),
"prophets_219": ("Que promessa repete duas vezes a sura Ash-Sharh?", ["«Com a dificuldade vem a facilidade»", "«A vitória está próxima»", "«O Paraíso está prometido»", "«Os inimigos perecerão»"], "«Com a dificuldade vem a facilidade. Com a dificuldade vem a facilidade»."),
"prophets_220": ("O que foi concedido ao Profeta ﷺ na sura Al-Kawthar, e o que lhe foi ordenado em troca?", ["Al-Kawthar; orar ao seu Senhor e sacrificar", "Um exército; combater", "Um reino; governar", "Um tesouro; reparti-lo"], "«Concedemos-te al-Kawthar. Ora, pois, ao teu Senhor e sacrifica»."),
"prophets_221": ("Como descreve a sura At-Tawba o Mensageiro ﷺ para com os crentes?", ["Solícito com eles, benévolo e misericordioso", "Duro e distante", "Rico e poderoso", "Calado e retirado"], "«Chegou-vos um Mensageiro de entre vós… solícito convosco, benévolo e misericordioso com os crentes»."),
"prophets_222": ("Segundo o Alcorão, o que teria afastado as pessoas do Profeta ﷺ, se ele fosse assim?", ["Ter sido áspero e duro de coração", "Ter sido rico", "Ter sido jovem", "Ter sido silencioso"], "«Por uma misericórdia de Allah foste suave com eles. Se fosses áspero e duro de coração, ter-se-iam dispersado à tua volta»."),
"prophets_223": ("O que diz o Alcorão do Mensageiro de Allah ﷺ para quem espera em Allah e no Último Dia?", ["É para eles um belo exemplo", "É um rei", "É um juiz", "É um guia de caravanas"], "«Tendes no Mensageiro de Allah um belo exemplo para quem espera em Allah e no Último Dia»."),
"prophets_224": ("A quem foi enviado o Profeta Muhammad ﷺ, segundo a sura Sabá?", ["A toda a humanidade", "Só aos Quraish", "Só aos árabes", "Ao povo de Medina"], "«Não te enviámos senão como anunciador e admoestador para toda a humanidade»."),
"prophets_225": ("Que versículo recitou o Profeta ﷺ quando os ídolos à volta da Caaba foram retirados?", ["«Chegou a verdade e desvaneceu-se o falso»", "«Demos-te uma vitória clara»", "«Diz: Ele é Allah, Um»", "«Quando chegar o socorro de Allah»"], "«E diz: chegou a verdade e desvaneceu-se o falso; o falso está destinado a desvanecer-se»."),
"prophets_226": ("O que dizem os crentes acerca dos mensageiros de Allah, no final da sura Al-Baqara?", ["«Não fazemos distinção entre nenhum dos Seus mensageiros»", "«Seguimos só o último»", "«Preferimos um deles»", "«Ignoramo-los»"], "«Não fazemos distinção entre nenhum dos Seus mensageiros. E disseram: ouvimos e obedecemos»."),
"prophets_227": ("Que mensagem comum levou todo mensageiro ao seu povo?", ["«Adorai Allah e afastai-vos do tagut»", "«Construí templos»", "«Enriquecei-vos»", "«Escrevei livros»"], "«Enviámos a cada comunidade um mensageiro: adorai Allah e afastai-vos do tagut»."),
"prophets_228": ("Em que língua foi enviado cada mensageiro, segundo a sura Ibrahim?", ["Na língua do seu povo, para lhes explicar", "Só em árabe", "Em hebraico", "Numa língua celeste"], "«Não enviámos nenhum mensageiro senão na língua do seu povo, para lhes explicar»."),
"prophets_229": ("O que foi revelado a cada mensageiro antes de Muhammad ﷺ, segundo a sura Al-Anbiya?", ["Que não há deus senão Ele: adorai-O, pois", "Construir um santuário", "Conquistar terras", "Guardar segredo"], "«Não enviámos antes de ti nenhum mensageiro sem lhe revelar: não há deus senão Eu, adorai-Me»."),
"prophets_230": ("Na sura Al-An'am, que grupo de profetas é enumerado como a descendência guiada de Ibrahim?", ["Dawud, Sulaiman, Ayyub, Yusuf, Musa e Harun, entre outros", "Só Musa e 'Isa", "Só Isma'il e Ishaq", "Só Nuh e Hud"], "A passagem enumera uma longa linhagem de profetas que Allah guiou, e diz: «Assim recompensamos os que fazem o bem»."),
"prophets_231": ("O que diz o Alcorão sobre os mensageiros uns em relação aos outros?", ["Allah favoreceu uns sobre os outros", "Todos têm o mesmo grau", "Só conta o último", "Ignoravam-se mutuamente"], "«Desses mensageiros, favorecemos uns sobre os outros»."),
"prophets_232": ("Que compromisso tomou Allah dos profetas, segundo a sura Al 'Imran?", ["Crer no Mensageiro que viria confirmando o que tinham, e apoiá-lo", "Nunca deixar o seu povo", "Construir cada um um templo", "Escrever cada um um livro"], "«Se vier a vós um Mensageiro que confirme o que tendes, haveis de crer nele e ampará-lo»."),
"prophets_233": ("Que profetas nomeia o Alcorão ao dizer que Allah lhes prescreveu a mesma religião?", ["Nuh, Ibrahim, Musa e 'Isa, junto com o revelado ao Profeta ﷺ", "Só Adão e Idris", "Só Dawud e Sulaiman", "Só Hud e Salih"], "«Prescreveu-vos em matéria de religião o que recomendou a Nuh, o que te revelámos a ti, e o que recomendámos a Ibrahim, a Musa e a 'Isa»."),
"prophets_234": ("O que diz o Alcorão sobre os mensageiros cuja história não relata?", ["Há alguns cuja história Allah não relatou ao Profeta ﷺ", "Não existem", "Todos estão nomeados", "Não têm importância"], "«Deles te relatámos a história de alguns, e de outros não ta relatámos»."),
"prophets_235": ("De entre quem escolheu Allah todos os Seus mensageiros, segundo a sura Yusuf?", ["De homens das cidades, a quem revelava", "Dos anjos", "Dos reis", "Só dos do deserto"], "«Não enviámos antes de ti senão homens das cidades, a quem revelávamos»."),
"prophets_236": ("O que recorda o Alcorão sobre os mensageiros desmentidos antes de Muhammad ﷺ?", ["Foram pacientes até lhes chegar o Nosso socorro", "Renderam-se", "Esconderam-se", "Mudaram a sua mensagem"], "«Já antes de ti foram desmentidos mensageiros, mas tiveram paciência perante o desmentido até lhes chegar o Nosso socorro»."),
"prophets_237": ("Que famílias escolheu Allah sobre os mundos, segundo a sura Al 'Imran?", ["Adão, Nuh, a família de Ibrahim e a família de 'Imran", "Os reis do Egito", "As tribos de Medina", "O povo de Sabá"], "«Allah escolheu Adão, Nuh, a família de Ibrahim e a família de 'Imran sobre os mundos»."),
"prophets_238": ("De que favores lembrou Musa o seu povo ao convidá-los a entrar na Terra Santa?", ["Que Allah pusera profetas entre eles e os fizera reis", "Que lhes dera navios", "Que lhes dera ouro", "Que lhes dera cavalos"], "«Ó meu povo, lembrai o favor de Allah convosco: pôs profetas entre vós e fez-vos reis»."),
"prophets_239": ("Como descreviam a Torá e o Evangelho o Profeta iletrado, segundo o Alcorão?", ["Ordena o bem, proíbe o mal e alivia-lhes os fardos", "Traz riqueza", "Governa pela força", "Constrói templos"], "«…o profeta iletrado que encontram mencionado na Torá e no Evangelho: ordena-lhes o bem e proíbe-lhes o mal… e livra-os do seu fardo»."),
"prophets_240": ("Em quem disse Nuh apoiar-se ao desafiar o seu povo a conspirar?", ["Em Allah, em quem depositava a sua confiança", "Nos seus filhos", "Na sua tribo", "No seu navio"], "«Em Allah confio. Ponde-vos de acordo, vós e os vossos associados»."),
"prophets_241": ("Na súplica de Ibrahim, a quem atribui ele a cura quando adoece?", ["Só a Allah", "Aos médicos", "Às plantas", "Ao tempo"], "«E quando adoeço, é Ele quem me cura», disse Ibrahim descrevendo o seu Senhor."),
"prophets_242": ("Com que foi resgatado o filho de Ibrahim, segundo a sura As-Saffat?", ["Com um sacrifício imenso", "Com um resgate de ouro", "Com uma caravana", "Com um rebanho inteiro"], "«E resgatámo-lo com um sacrifício imenso»."),
"prophets_243": ("Em que declaram crer os crentes no versículo «Dizei: cremos em Allah…»?", ["No revelado a Ibrahim, Isma'il, Ishaq, Ya'qub, Musa, 'Isa e aos profetas", "Num só livro", "Num só profeta", "Nas suas próprias tradições"], "«Dizei: cremos em Allah e no que nos foi revelado, e no que foi revelado a Ibrahim, Isma'il, Ishaq, Ya'qub…»"),
"prophets_244": ("Porque relata Allah ao Profeta ﷺ as histórias dos mensageiros?", ["Para lhe firmar o coração", "Para o entreter", "Para lhe ensinar história", "Para o distrair"], "«E tudo o que te relatamos das notícias dos mensageiros é para com isso firmar o teu coração»."),
"prophets_245": ("O que foi ordenado ao Profeta ﷺ dizer de si mesmo, no fim da sura Al-Kahf?", ["«Eu não sou senão um homem como vós; foi-me revelado que o vosso Deus é um Deus Único»", "«Sou um rei»", "«Sou um anjo»", "«Conheço o oculto»"], "«Diz: eu não sou senão um homem como vós, a quem foi revelado que o vosso Deus é um Deus Único»."),
"prophets_246": ("Como descreve a sura Al-Fath aqueles que estão com o Mensageiro ﷺ?", ["Duros com os incrédulos, misericordiosos entre si", "Ricos e numerosos", "Silenciosos e retirados", "Viajantes e comerciantes"], "«Muhammad é o Mensageiro de Allah. E os que estão com ele são duros com os incrédulos, misericordiosos entre si»."),
"prophets_247": ("O que diz a sura An-Najm sobre as palavras do Profeta ﷺ?", ["Não fala por capricho: não é senão uma revelação inspirada", "Fala como poeta", "Fala como adivinho", "Fala por si próprio"], "«O vosso companheiro não se extraviou nem se desviou; não fala por capricho: não é senão uma revelação inspirada»."),
"prophets_248": ("O que foi ordenado ao Profeta ﷺ quando chegou o socorro de Allah e a vitória?", ["Glorificar o seu Senhor com louvor e pedir-Lhe perdão", "Celebrar com um banquete", "Erguer um monumento", "Descansar"], "«Quando chegar o socorro de Allah e a vitória… glorifica o teu Senhor com louvor e pede-Lhe perdão»."),
"prophets_249": ("Que três tarefas atribui a sura Al-Jumu'a ao Mensageiro enviado aos iletrados?", ["Recitar-lhes os versículos, purificá-los e ensinar-lhes o Livro e a sabedoria", "Construir, comerciar e governar", "Escrever, contar e viajar", "Julgar, castigar e cobrar"], "«Ele é quem enviou entre os iletrados um Mensageiro de entre eles, que lhes recita os Seus versículos, os purifica e lhes ensina o Livro e a sabedoria»."),
"prophets_250": ("Que salvaguarda menciona o Alcorão enquanto o Profeta ﷺ estava entre eles?", ["Allah não os castigaria enquanto ele estivesse entre eles", "Seriam ricos", "Venceriam sempre", "Não morreriam"], "«Mas Allah não os iria castigar estando tu entre eles»."),
}
